# Data type: arbitrary string
# Used widely as keys, URIs, category names, filters, playlist names, device ids, etc.
# Goals for interesting yet valid inputs:
# - mixture of ASCII words, unicode, whitespace, punctuation
# - include common key-like tokens (artist, album, title, genre)
# - include category/playlist names, device-like ids
# - include path-like and URI-like forms to benefit filename/URI consumers
# - include short strings, empty string, and moderately long strings
# - ensure null-terminated when interpreted as C-string (fuzzer infra adds c_str())
# We return raw bytes; the fuzz framework will split or use entire blob for FUZZ_PARAM_STR/FILENAME.

MAX_SIZE = 4096

COMMON_TOKENS = [
    "artist", "album", "title", "track", "genre", "year", "rating",
    "playcount", "bitrate", "duration", "filepath", "filename", "uri",
    "external_id", "playlist", "device.default", "output", "eq.enabled",
    "replaygain.mode", "transport", "category", "composer", "albumartist",
]

COMMON_EXTS = ["mp3", "flac", "ogg", "wav", "m4a", "aac", "opus", "aiff"]

COMMON_SCHEMES = ["file", "http", "https", "ftp", "smb", "nfs", "custom"]

UNICODE_SAMPLES = [
    "café", "naïve", "東京", "Музыка", " música ", "歌曲", "🎵🎶", "½¾∆µ", "שָׁלוֹם",
]

