PUNCT = "_-.,:+@#[](){}!$%^&=~"  # safe-ish filename/pref keys punctuation


def _rand_ascii(r: random.Random, n: int) -> str:
    letters = string.ascii_letters + string.digits + PUNCT
    return "".join(r.choice(letters) for _ in range(n))


def _rand_word(r: random.Random) -> str:
    which = r.randrange(5)
    if which == 0:
        return r.choice(COMMON_TOKENS)
    if which == 1:
        return _rand_ascii(r, r.randint(3, 12))
    if which == 2:
        return r.choice(UNICODE_SAMPLES)
    if which == 3:
        # numeric-like
        return str(r.randint(0, 10**6))
    # mixed
    return _rand_ascii(r, r.randint(1, 6)) + r.choice(["-", "_", ":"]) + _rand_ascii(r, r.randint(1, 6))


def _build_key_value(r: random.Random) -> str:
    key = _rand_word(r)
    val_choice = r.randrange(6)
    if val_choice == 0:
        val = r.choice(COMMON_TOKENS)
    elif val_choice == 1:
        val = r.choice(UNICODE_SAMPLES)
    elif val_choice == 2:
        val = str(r.randint(0, 500000))
    elif val_choice == 3:
        val = "true" if r.choice([True, False]) else "false"
    elif val_choice == 4:
        val = f"{r.uniform(-100.0, 100.0):.3f}"
    else:
        val = _rand_ascii(r, r.randint(1, 16))
    sep = r.choice(["=", ":", " ", "\t"])
    return f"{key}{sep}{val}"


def _build_uri(r: random.Random) -> str:
    scheme = r.choice(COMMON_SCHEMES)
    if scheme == "file":
        # Build a platform-agnostic path-like
        parts: List[str] = []
        depth = r.randint(1, 4)
        for _ in range(depth):
            parts.append(_rand_ascii(r, r.randint(3, 10)))
        base = "/" + "/".join(parts)
        name = _rand_ascii(r, r.randint(3, 10))
        ext = r.choice(COMMON_EXTS)
        return f"file://{base}/{name}.{ext}"
    else:
        host = _rand_ascii(r, r.randint(4, 10)).lower()
        tld = r.choice(["com", "org", "net", "local"])
        path_parts = [ _rand_ascii(r, r.randint(2, 8)) for _ in range(r.randint(0, 3)) ]
        qs = ""
        if r.random() < 0.6:
            params = [f"{_rand_ascii(r, r.randint(2,6))}={_rand_ascii(r, r.randint(1,6))}" for _ in range(r.randint(1,3))]
            qs = "?" + "&".join(params)
        port = ":%d" % r.choice([80, 443, 8000, 6600, 12345]) if r.random() < 0.4 else ""
        path = ("/" + "/".join(path_parts)) if path_parts else ""
        return f"{scheme}://{host}.{tld}{port}{path}{qs}"


def _build_filename(r: random.Random) -> str:
    # Relative or absolute looking path
    parts: List[str] = []
    if r.random() < 0.5:
        parts.append("")  # leads to starting '/'
    depth = r.randint(0, 3)
    for _ in range(depth):
        parts.append(_rand_ascii(r, r.randint(2, 10)))
    name = _rand_ascii(r, r.randint(3, 12))
    ext = r.choice(COMMON_EXTS)
    path = "/".join(parts + [f"{name}.{ext}"])
    if path and path[0] != "/" and r.random() < 0.3:
        path = "./" + path
    return path


def _build_device_id(r: random.Random) -> str:
    pref = r.choice(DEVICE_ID_PREFIX)
    core = _rand_ascii(r, r.randint(4, 12))
    if r.random() < 0.5:
        core += ":" + _rand_ascii(r, r.randint(4, 8))
    return pref + core


def _build_playlist_name(r: random.Random) -> str:
    words = [r.choice(COMMON_TOKENS) for _ in range(r.randint(1, 3))]
    if r.random() < 0.5:
        words.append(str(r.randint(1, 2025)))
    return " ".join(words).title()


def _build_category_query(r: random.Random) -> str:
    # e.g., "genre:rock", "albumartist=Beatles", supports filters
    kvs = [_build_key_value(r) for _ in range(r.randint(1, 3))]
    if r.random() < 0.5:
        kvs.append("filter=" + r.choice(["recent", "favorite", "rated>=4"]))
    return " ".join(kvs)


def _add_whitespace_variants(r: random.Random, s: str) -> str:
    # Surround or intersperse with whitespace to exercise Trim/Split paths
    if r.random() < 0.4:
        s = r.choice(WHITES) * r.randint(1, 3) + s + r.choice(WHITES) * r.randint(1, 3)
    if r.random() < 0.3:
        s = s.replace(" ", r.choice(["\t", "  "]))
    return s


def _chunks_join(chunks: List[str]) -> bytes:
    blob = "\n".join(chunks)
    b = blob.encode("utf-8", errors="ignore")
    if len(b) > MAX_SIZE:
        b = b[:MAX_SIZE]
    return b


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    chunks: List[str] = []

    # Mix of small primitives
    for _ in range(r.randint(2, 5)):
        s = _rand_word(r)
        chunks.append(_add_whitespace_variants(r, s))

    # Keys and values lines
    for _ in range(r.randint(1, 3)):
        chunks.append(_add_whitespace_variants(r, _build_key_value(r)))

    # Playlist names
    for _ in range(r.randint(1, 2)):
        chunks.append(_build_playlist_name(r))

    # Device IDs
    for _ in range(r.randint(0, 2)):
        chunks.append(_build_device_id(r))

    # Filenames and URIs
    for _ in range(r.randint(1, 3)):
        chunks.append(_build_filename(r))
    for _ in range(r.randint(1, 3)):
        chunks.append(_build_uri(r))

    # Category-like queries
    for _ in range(r.randint(1, 2)):
        chunks.append(_build_category_query(r))

    # Extension-like tokens
    for _ in range(r.randint(1, 2)):
        chunks.append("." + r.choice(COMMON_EXTS))

    # Sometimes include an empty line and purely whitespace to trigger edge paths
    if r.random() < 0.5:
        chunks.append("")
    if r.random() < 0.5:
        chunks.append("\t \r\n")

    # Ensure we have at least one long-ish string to test larger buffers
    long_part = []
    while len("".join(long_part)) < r.randint(128, 512):
        long_part.append(_rand_ascii(r, r.randint(5, 20)))
    chunks.append(" ".join(long_part))

    return _chunks_join(chunks)

import os
import random
import string
import sys
from typing import List

# Data type: filesystem path
# Goal: Return a bytes object containing a valid path string suitable for FUZZ_PARAM_FILENAME/STR consumers.
# Strategy:
# - Prefer generating existing, readable temporary files or directories to satisfy stubs that require existence.
# - Provide variety: sometimes return a directory path, sometimes a file path, sometimes an absolute/relative path.
# - Keep contents small (<4k). No I/O beyond creating temp files/dirs under the system temp directory.
# - Seeded randomness via the provided seed.

# Helper: safe temp root
def _tmp_root() -> str:
    # Cross-platform temp base
    return os.path.abspath(os.getenv('TMPDIR') or os.getenv('TEMP') or os.getenv('TMP') or '/tmp')

def _rand_name(rng: random.Random, min_len=6, max_len=12) -> str:
    # Mix alnum and a couple of safe symbols
    alphabet = string.ascii_letters + string.digits + "-_"
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(alphabet) for _ in range(n))

def _ensure_dir(path: str):
    os.makedirs(path, exist_ok=True)

def _create_file_with_data(path: str, rng: random.Random, size_limit: int = 1024):
    # Create a file with random bytes up to size_limit
    # Ensure parent exists
    _ensure_dir(os.path.dirname(path))
    # Keep deterministic content per seed
    size = rng.randint(0, size_limit)
    data = rng.randbytes(size) if hasattr(rng, 'randbytes') else bytes(rng.getrandbits(8) for _ in range(size))
    with open(path, 'wb') as f:
        f.write(data)

def _make_deep_dir_structure(base: str, rng: random.Random) -> str:
    # Create 1-3 nested directories
    depth = rng.randint(1, 3)
    cur = base
    for _ in range(depth):
        cur = os.path.join(cur, _rand_name(rng))
    _ensure_dir(cur)
    # Optionally populate with a few files to exercise scanDirectory
    for _ in range(rng.randint(0, 5)):
        fp = os.path.join(cur, _rand_name(rng) + ".bin")
        _create_file_with_data(fp, rng, size_limit=256)
    return cur

def _maybe_make_relative(path: str, rng: random.Random) -> str:
    # Convert to relative with respect to cwd with some probability if possible
    if rng.random() < 0.35:
        try:
            cwd = os.getcwd()
            rel = os.path.relpath(path, cwd)
            return rel
        except Exception:
            return path
    return path

def _add_platform_variants(path: str, rng: random.Random) -> str:
    # Occasionally add ./ or normalize separators, or trailing separator for directories
    p = path
    # Prepend ./ for relative feel
    if rng.random() < 0.25 and not os.path.isabs(p):
        p = os.path.join('.' + os.sep, p)
    # Trailing separator for directories with some chance
    try:
        if os.path.isdir(path) and rng.random() < 0.5:
            if not p.endswith(os.sep):
                p = p + os.sep
    except Exception:
        pass
    return p

def _gen_existing_file_path(rng: random.Random) -> str:
    base = os.path.join(_tmp_root(), "fuzz_paths")
    _ensure_dir(base)
    # Optionally nest directories
    if rng.random() < 0.6:
        base = _make_deep_dir_structure(base, rng)
    name = _rand_name(rng) + ("." + rng.choice(["dat", "bin", "txt", "raw"]))
    path = os.path.join(base, name)
    _create_file_with_data(path, rng, size_limit=1024)
    path = _maybe_make_relative(path, rng)
    return _add_platform_variants(path, rng)

def _gen_existing_dir_path(rng: random.Random) -> str:
    base = os.path.join(_tmp_root(), "fuzz_dirs")
    _ensure_dir(base)
    d = _make_deep_dir_structure(base, rng)
    d = _maybe_make_relative(d, rng)
    return _add_platform_variants(d, rng)

def _gen_plausible_nonexistent_path(rng: random.Random) -> str:
    # Construct a path that likely doesn't exist but is syntactically valid
    base = os.path.join(_tmp_root(), "fuzz_missing")
    # Do not create the leaf
    parts = [_rand_name(rng) for _ in range(rng.randint(1, 3))]
    p = os.path.join(base, *parts)
    # 50% chance to make it look like a file
    if rng.random() < 0.5:
        p = p + "." + rng.choice(["nope", "missing", "ghost"]) 
    p = _maybe_make_relative(p, rng)
    return _add_platform_variants(p, rng)

def _choose_variant(rng: random.Random) -> str:
    # Weights tuned to satisfy stubs that expect existing files/dirs more often
    # 0: existing file, 1: existing dir, 2: non-existent plausible path
    choice = rng.choices([0, 1, 2], weights=[0.5, 0.3, 0.2], k=1)[0]
    if choice == 0:
        return _gen_existing_file_path(rng)
    elif choice == 1:
        return _gen_existing_dir_path(rng)
    else:
        return _gen_plausible_nonexistent_path(rng)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    path = _choose_variant(rng)
    # Ensure the total size is <= 4096 bytes
    encoded = path.encode(sys.getfilesystemencoding() or 'utf-8', errors='surrogateescape')
    if len(encoded) > 4096:
        encoded = encoded[:4096]
    return encoded
